Implement the Verilog module based on the following description.
Given the finite state machine circuit described below.

// Build this circuit in Verilog.

// Input i goes to three different two-input gates: a NOR, a NAND, and an XOR gate. Each of the three gates is connected to the input of a D flip-flop and then the flip-flop outputs all go to a three-input XOR, whose output is T. The second input of the NOR is its corresponding flip-flop's output, the second input of the NAND is its corresponding flip-flop's complemented output, and finally the second input of the XOR is its corresponding flip-flop's complementary output.
module fsm_module6 (
	input clk,
	input i,
	output t);

code:
module fsm_module6 (
	input clk,
	input i,
	output t);reg [2:0] state = 0;

	always @(posedge clk) begin
		state <= { ~(state[2] | i), ~(state[1] & ~i), state[0] ^ ~i };
	end

	assign t = state[2] ^ state[1] ^ state[0];

endmodule

