assign b = (ra_rf != 0) && (ra_mem == ra_rf);
assign c = (ra_rf != 0) && (ra_wb == ra_rf);

always@(a or b or c or r_ex or r_mem or r_wb or r_rf)
begin
	if(a == 1)
		r = r_ex;
	else if(b == 1)
		r = r_mem;
	else if(c == 1)
		r = r_wb;
	else
		r = r_rf;

end

