Implement the Verilog module based on the following description.
Module R implements the boolean function t = a ^ b.

// Module S can be described by the following simulation waveform: 

If a = 1, b = 1, then t = 0.
If a = 0, b = 1, then t = 1.
If a = 0, b = 0, then t = 0.
If a = 1, b = 0, then t = 1.

// Now consider a top-level that uses two R submodules and two S submodules. The first input of all four submodules is connect to input 'a', and the second input of all four submodules is connected to 'b'. The output of the first R submodule is connected to a two-input OR, along with the output of the first S submodule. The second pair of R and S submodules is similarly connected to an AND gate. The output of the OR and the AND is connected to an XOR, whose output is 't'.

// Implement this circuit in Verilog.

module top_module(
    input a,
    input b,
    output t);

code:
module R(
    input a,
    input b,
    output t
);
    assign t = a ^ b;
endmodule

module S(
    input a,
    input b,
    output t
);
    assign t = a ^ b;
endmodule

module top_module(
    input a,
    input b,
    output t
);
    wire r1_out, r2_out, s1_out, s2_out;
    wire or_out, and_out, xor_out;

    R r1(.a(a), .b(b), .t(r1_out));
    R r2(.a(a), .b(b), .t(r2_out));
    S s1(.a(a), .b(b), .t(s1_out));
    S s2(.a(a), .b(b), .t(s2_out));

    assign or_out = r1_out | s1_out;
    assign and_out = r2_out & s2_out;
    assign t = or_out ^ and_out;
endmodule

