description:
Design a binary encoder that converts one of several input signals into its corresponding binary output representation. This encoder prioritizes active input signals, encoding them into a simpler output format, where the output bits reflect the position of the highest significant input that is set to 1. It is configured for 8 input signals, producing a 2-bit binary output to represent the active input, facilitating the process of signal reduction in digital systems.
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);

code:
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);parameter n = 4; // number of input signals
parameter m = 2; // number of output signals

// Priority encoder logic
assign out[0] = (in[0] == 1) ? 1 :
                (in[1] == 1) ? 2 :
                (in[2] == 1) ? 3 :
                (in[3] == 1) ? 4 : 0;
assign out[1] = (in[4] == 1) ? 5 :
                (in[5] == 1) ? 6 :
                (in[6] == 1) ? 7 :
                (in[7] == 1) ? 8 : 0;

// Binary encoder logic
assign out[0] = in[0] + in[1]*2 + in[2]*4 + in[3]*8;
assign out[1] = in[4] + in[5]*2 + in[6]*4 + in[7]*8;

endmodule

